async function refreshProviderIntegrationControls(){const panel=$('#integrationStatus');if(!panel)return;try{const [response,statusResponse]=await Promise.all([fetch('/api/integrations',{cache:'no-store'}),fetch('/api/provider-status',{cache:'no-store'})]),data=await response.json(),status=statusResponse.ok?await statusResponse.json():{connections:[]};if(!response.ok)return;const connected=Object.fromEntries((status.connections||[]).map(item=>[item.provider,item])),rows=$$('.integration',panel);data.integrations.forEach((item,index)=>{if(!['google','meta'].includes(item.id)||!rows[index])return;const row=rows[index],detail=row.querySelector('p'),pill=row.querySelector('.pill'),saved=connected[item.id==='google'?'google_business':'meta'];row.querySelector('[data-provider-connect]')?.remove();if(saved){if(detail)detail.textContent=`Connected securely · ${saved.accounts?.length||0} account${saved.accounts?.length===1?'':'s'}`;if(pill){pill.textContent='Connected';pill.className='pill green'}return}if(item.configured&&!item.enabled){if(detail)detail.textContent='Secrets configured · activation intentionally disabled';if(pill){pill.textContent='Disabled';pill.className='pill orange'}return}if(item.configured&&item.enabled){if(detail)detail.textContent='Ready for explicit account authorization';if(pill){pill.textContent='Available';pill.className='pill green'}const button=document.createElement('a');button.className='ghost-button integration-guide';button.dataset.providerConnect=item.id;button.href=item.id==='google'?'/api/google-connect':'/api/meta-connect';button.textContent=item.id==='google'?'Connect Google':'Connect Meta';row.append(button)}})}catch{}}
async function mountGa4Panel(){if(location.hash!=='#analytics'||$('#ga4LivePanel'))return;const page=$('#app');if(!page)return;const section=document.createElement('section');section.id='ga4LivePanel';section.className='card';section.style.marginTop='18px';section.innerHTML='<div class="card-header"><div><h2 class="card-title">Google Analytics 4</h2><p class="card-subtitle">Checking for a secure read-only connection…</p></div><span class="pill">Checking</span></div>';page.append(section);try{const response=await fetch('/api/provider-status',{cache:'no-store'});if(response.status===401){section.querySelector('.card-subtitle').textContent='Sign in to connect and load real GA4 reporting data.';section.querySelector('.pill').textContent='Sign in required';return}const data=await response.json(),connection=data.connections?.find(item=>item.provider==='google_analytics');if(!connection){section.querySelector('.card-subtitle').textContent='No GA4 property connected. Demo analytics above remain clearly labelled.';section.querySelector('.pill').textContent='Not connected';return}const properties=(connection.accounts||[]).flatMap(account=>(account.properties||[]).map(property=>({...property,accountName:account.displayName})));section.innerHTML=`<div class="card-header"><div><h2 class="card-title">Live Google Analytics 4</h2><p class="card-subtitle">Read-only · last 30 days · loaded only when requested</p></div><span class="pill green">Connected</span></div><div class="live-audit-form"><select id="ga4Property">${properties.map(property=>`<option value="${escapeHtml(property.property)}">${escapeHtml(property.displayName)} · ${escapeHtml(property.accountName)}</option>`).join('')}</select><button class="primary-button" id="loadGa4Report" ${properties.length?'':'disabled'}>Load 30-day report</button></div><div id="ga4ReportOutput" class="muted" style="margin-top:16px">${properties.length?'Choose a property and load the report.':'No accessible GA4 properties were returned.'}</div>`;$('#loadGa4Report').onclick=loadGa4Report}catch{section.querySelector('.card-subtitle').textContent='GA4 connection status is temporarily unavailable.';section.querySelector('.pill').textContent='Unavailable'}}
async function loadGa4Report(event){const button=event.currentTarget,output=$('#ga4ReportOutput'),property=$('#ga4Property').value;button.disabled=true;button.textContent='Loading…';try{const response=await fetch('/api/ga4-report',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({property})}),data=await response.json();if(!response.ok)throw new Error(data.message||data.error||'Report unavailable');const totals=data.report.totals?.[0]?.metricValues||[],rows=data.report.rows||[],value=index=>Number(totals[index]?.value??rows.reduce((sum,row)=>sum+Number(row.metricValues?.[index]?.value||0),0)).toLocaleString('en-IN');output.className='grid stats-grid';output.innerHTML=`${stat('Active users',value(0),'GA4 · last 30 days','♙')}${stat('Sessions',value(1),'GA4 · last 30 days','↗')}${stat('Views',value(2),'GA4 · last 30 days','◉')}${stat('Key events',value(3),'GA4 · last 30 days','✓')}`}catch(error){output.className='notice';output.textContent=error.message}finally{button.disabled=false;button.textContent='Load 30-day report'}}
const seoFixGuides={
  'Title tag':{priority:'High',why:'The title is the clearest page-level search result label.',steps:['Write one unique title for this page.','Keep the main service and location close to the beginning.','Aim for roughly 10–60 characters and avoid keyword repetition.']},
  'Meta description':{priority:'Medium',why:'A clear description can improve how the result communicates value to searchers.',steps:['Summarize the page in one useful sentence.','Include the main service, location and a truthful call to action.','Aim for roughly 50–160 characters.']},
  'Single H1':{priority:'High',why:'One descriptive H1 makes the main page topic easier to understand.',steps:['Keep one visible H1 that describes the page.','Change additional H1 elements to H2 or H3.','Do not hide the H1 or fill it with repeated keywords.']},
  'Mobile viewport':{priority:'High',why:'A viewport tag helps the page render correctly on phones.',steps:['Add <meta name="viewport" content="width=device-width, initial-scale=1"> inside <head>.','Test the page at small screen widths.']},
  'Canonical URL':{priority:'Medium',why:'A canonical link identifies the preferred URL for similar page variants.',steps:['Choose the final HTTPS URL for this page.','Add one absolute rel="canonical" link in <head>.','Make sure it does not point to an unrelated page.']},
  'Image ALT text':{priority:'Medium',why:'Useful ALT text supports accessibility and image understanding.',steps:['Describe the purpose or content of each meaningful image.','Use empty alt text for purely decorative images.','Avoid stuffing service keywords into every image.']},
  'JSON-LD schema':{priority:'Low',why:'Valid structured data can help search engines understand eligible business details.',steps:['Add JSON-LD that matches visible page content.','For a local business, verify name, address, phone, hours and URL.','Validate the result and keep it aligned with Google Business Profile.']},
  'LocalBusiness schema':{priority:'Medium',why:'Explicit local-business data helps search engines connect the website with the verified business entity.',steps:['Add a LocalBusiness or more specific subtype such as BeautySalon to the server HTML.','Use only verified name, address, phone, hours and canonical URL.','Keep the values aligned with visible website content and Google Business Profile.']},
  'Indexability':{priority:'High',why:'A noindex directive can prevent the page from appearing in search results.',steps:['Confirm whether this page should be public in search.','Remove noindex only when the page is complete and intended for indexing.','Check both meta robots and response headers.']},
  'HTML language':{priority:'Low',why:'The language attribute helps browsers and assistive technology interpret content.',steps:['Add a valid lang value to the html element, such as en or bn.','Use the primary language of the page.']},
  default:{priority:'Medium',why:'This structural issue may affect clarity, accessibility or crawlability.',steps:['Review the latest audit detail.','Update the page template and rerun the live audit.']}
};
function seoFixModal(name){const guide=seoFixGuides[name]||seoFixGuides.default,d=modal(`Fix: ${name}`,`<div class="fix-modal-head"><span class="priority ${guide.priority.toLowerCase()}">${guide.priority} priority</span><p>${escapeHtml(guide.why)}</p></div><ol class="fix-steps">${guide.steps.map(step=>`<li>${escapeHtml(step)}</li>`).join('')}</ol><p class="muted">Make the change on the website, publish it, then rerun the live URL audit. Search visibility depends on many factors beyond this structural checklist.</p>`,'Close');d.onsubmit=event=>{event.preventDefault();d.close()}}
function metadataModal(){const city=String(state.business.address||'').split(',')[0].trim(),category=state.business.category||'Local business',rawTitle=`${category}${city?` in ${city}`:''} | ${state.business.name}`,title=rawTitle.slice(0,60),base=state.business.description||`${state.business.name} offers personalised ${category.toLowerCase()} services${city?` in ${city}`:''}.`,description=`${base} Explore services and contact our team to book a consultation.`.slice(0,155),d=modal('Recommended page metadata',`<div class="field"><label>SEO title · ${title.length} characters</label><textarea id="metaTitle" style="min-height:75px">${escapeHtml(title)}</textarea></div><div class="field" style="margin-top:14px"><label>Meta description · ${description.length} characters</label><textarea id="metaDescription" style="min-height:120px">${escapeHtml(description)}</textarea></div><p class="muted">Review every claim and make each page title and description unique.</p>`,'Copy metadata');d.onsubmit=event=>{event.preventDefault();navigator.clipboard?.writeText(`Title: ${$('#metaTitle').value}\nMeta description: ${$('#metaDescription').value}`);d.close();toast('Metadata copied')}}
