function channelSpendModal(){const channels=['Google','Instagram','Facebook','Website','Referral','Other'],d=modal('Monthly channel spend',`<p class="muted">Enter the amount for the same reporting period used in Analytics. These values stay in your workspace and do not create ad-platform charges.</p><div class="form-grid">${channels.map(channel=>`<div class="field"><label>${channel} spend ₹</label><input name="${channel}" type="number" min="0" step="1" value="${Number(state.channelSpend[channel]||0)}"></div>`).join('')}</div>`,'Save spend');d.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(d.querySelector('form')||event.currentTarget));channels.forEach(channel=>state.channelSpend[channel]=Math.max(0,Number(data[channel])||0));save();d.close();route('analytics');toast('Channel spend saved')}}
function exportAnalyticsReport(){const normalize=source=>source==='Website form'?'Website':source||'Other',sources=[...new Set([...Object.keys(state.channelSpend),...state.leads.map(lead=>normalize(lead.source))])],active=state.appointments.filter(item=>item.status!=='Cancelled'),revenue=active.reduce((sum,item)=>sum+(Number(item.value)||0),0),spend=Object.values(state.channelSpend).reduce((sum,value)=>sum+(Number(value)||0),0),rows=[['MarketingMind performance report'],['Exported',new Date().toISOString()],['Total spend',spend],['CRM leads',state.leads.length],['Active booking value',revenue],['Estimated ROI',spend?`${Math.round((revenue-spend)/spend*100)}%`:'Not available'],[],['Source','Spend','Leads','Booked','Conversion','Cost per lead'],...sources.map(source=>{const leads=state.leads.filter(lead=>normalize(lead.source)===source),booked=leads.filter(lead=>lead.status==='Booked').length,channelSpend=Number(state.channelSpend[source]||0);return [source,channelSpend,leads.length,booked,leads.length?`${Math.round(booked/leads.length*100)}%`:'0%',channelSpend&&leads.length?Math.round(channelSpend/leads.length):'']})];downloadText(rows.map(row=>row.map(csvCell).join(',')).join('\n'),`marketingmind-performance-${new Date().toISOString().slice(0,10)}.csv`);toast('Analytics report exported')}
