  $('#saveVoiceProfile')?.addEventListener('click',()=>{const name=$('#voiceProfileName').value.trim(),language=$('#voiceProfileLanguage').value.trim(),files=[...$('#voiceSamples').files];if(!name||!language){toast('Add a profile name and language');return}if(!$('#voiceConsent').checked){toast('Verified voice consent is required');return}if(!files.length){toast('Add at least one voice sample');return}state.voiceProfiles.unshift({name,language,samples:files.map(file=>({name:file.name,size:file.size,type:file.type})),consent:true,created:new Date().toISOString()});save();route('media');toast('Consented voice profile saved')});
