  $('#saveVoiceAsset')?.addEventListener('click',()=>{const script=$('#voiceScript').value.trim();if(!script){$('#voiceScript').focus();toast('Add a script first');return}state.mediaAssets.unshift({title:script.slice(0,55),type:'Voiceover',format:$('#voiceChoice').value,status:'Brief ready',content:script,language:$('#voiceLanguage').value,speed:$('#voiceSpeed').value,created:new Date().toISOString()});save();route('media');toast('Voiceover brief saved to Asset Library')});
  $('#saveImageAsset')?.addEventListener('click',()=>{const prompt=$('#imagePrompt').value.trim();if(!prompt){$('#imagePrompt').focus();toast('Describe the image first');return}state.mediaAssets.unshift({title:prompt.slice(0,55),type:'Image',format:$('#imageFormat').value,status:'Brief ready',content:prompt,style:$('#imageStyle').value,brand:$('#imageBrand').value,created:new Date().toISOString()});save();route('media');toast('Image brief saved to Asset Library')});
  $$('[data-delete-media]').forEach(button=>button.onclick=()=>{if(!confirm('Remove this media asset?'))return;state.mediaAssets.splice(Number(button.dataset.deleteMedia),1);save();route('media');toast('Media asset removed')});
  $('#discoverKeywords')?.addEventListener('click',discoverKeywordIdeas);
