  $('#analyzeCompetitor')?.addEventListener('click',()=>{const value=$('#competitorDomain').value.trim();if(!value){$('#competitorDomain').focus();return}let host;try{host=new URL(value).hostname}catch{toast('Enter a complete competitor website URL');return}$('#competitorResult').innerHTML=`<b>${escapeHtml(host)}</b> added for comparison. Connect a live keyword provider to retrieve verified gaps; meanwhile review service, location, pricing and question topics that your mapped pages do not cover.`});
